def climb_stairs(n):
    if n <= 2:
        return n
    ways = [0] * (n + 1)
    ways[1] = 1                                   # exactly 1 way to reach the first step
    ways[2] = 2                                   # exactly 2 ways to reach the second step
    for i in range(3, n + 1):
        ways[i] = ways[i - 1] + ways[i - 2]           # combine the two ways to arrive at this step
    return ways[n]


if __name__ == "__main__":
    n = 5
    print(climb_stairs(n))

