def climb_stairs(n):
    if n <= 2:
        return n
    prev2, prev1 = 1, 2                          # ways to reach step 1 and step 2
    for i in range(3, n + 1):
        current = prev1 + prev2                     # combine the two most recent step counts
        prev2, prev1 = prev1, current                 # slide both values forward by one step
    return prev1


if __name__ == "__main__":
    n = 5
    print(climb_stairs(n))

